//! 🏠️ One preborn actor job state retains real sources and output bodies through Source-funded calls.
use semio_framework_actor::{OriginalJobSource,OriginalJobStep,OriginalJobOutcome,OriginalJobOutputState,OriginalActorJobProvider,RetainedTurnInput};
use semio_framework_job::{StepContext,OriginalTurnFailure};
use semio_framework_value::{OriginalRetirementPoll,RetainedAllocationEffect,RetainedWorkPoll,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetirementDemand,ValueError,ValueRefusalKind,retirement::controlled::ControlledRetirement};
use std::mem::ManuallyDrop;
pub struct OriginalActorJobState{source:ManuallyDrop<Option<OriginalJobSource>>,source_retirement:ManuallyDrop<Option<ControlledRetirement<OriginalJobSource>>>,registered:bool,offset:usize,ack:bool,job_output_chunk_borrowed:bool,chunk:ManuallyDrop<Option<Vec<u8>>>,chunk_retirement:ManuallyDrop<Option<ControlledRetirement<Vec<u8>>>>,identity:Option<(u64,u64,u64)>,output:ManuallyDrop<Option<OriginalJobStep>>,output_retirement:ManuallyDrop<Option<ControlledRetirement<OriginalJobStep>>>}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
fn permits(grant:RetainedCloneGrant,d:RetirementDemand)->bool{grant.maximum_items!=0&&grant.maximum_copy_bytes>=d.copy_bytes&&grant.maximum_capacity_bytes>=d.capacity_bytes&&grant.maximum_release_bytes>=d.release_bytes&&grant.maximum_depth>=d.depth}
fn nested(mut d:RetirementDemand)->Result<RetirementDemand,ValueError>{d.depth=d.depth.checked_add(1).ok_or_else(||invalid("actor owned retirement depth overflow"))?;Ok(d)}
fn metadata()->RetainedCloneStep{RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()})}
fn slot_demands<T:semio_framework_value::retirement::RetireOwned>(source:&ManuallyDrop<Option<T>>,retirement:&ManuallyDrop<Option<ControlledRetirement<T>>>,copy:usize)->Result<RetirementDemand,ValueError>{if let Some(owner)=retirement.as_ref(){if !owner.terminal_is_empty(){return nested(RetirementDemand{copy_bytes:owner.next_copy_byte_demand()?,capacity_bytes:owner.next_capacity_byte_demand(copy)?,release_bytes:owner.next_release_byte_demand()?,depth:owner.next_depth_demand()?})}return Ok(RetirementDemand{depth:1,..Default::default()})}Ok(RetirementDemand{depth:usize::from(source.is_some()),..Default::default()})}
fn charge(effect:&mut RetainedAllocationEffect<'_>,work:&mut u128)->Result<(),ValueError>{if !effect.performed(1)?{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"actor slot close exceeds its effect quote"))}*work=effect.performed_work();Ok(())}
fn poll_step(poll:OriginalRetirementPoll)->Result<RetainedCloneStep,ValueError>{match poll{RetainedWorkPoll::Complete(turn)=>turn.result.map_err(|failure|failure.into_value_error()),RetainedWorkPoll::Pending{..}=>Ok(RetainedCloneStep::Progress(Default::default()))}}
pub fn close_owned_actor_slot<T:semio_framework_value::retirement::RetireOwned>(source:&mut ManuallyDrop<Option<T>>,retirement:&mut ManuallyDrop<Option<ControlledRetirement<T>>>,effect:&mut RetainedAllocationEffect<'_>,work:&mut u128)->Result<RetainedCloneStep,ValueError>{let grant=effect.grant();if source.is_some()&&retirement.is_none(){if !permits(grant,RetirementDemand{depth:1,..Default::default()}){return Ok(RetainedCloneStep::Progress(Default::default()))}charge(effect,work)?;let original=source.take().ok_or_else(||invalid("actor original slot disappeared"))?;match ControlledRetirement::new(original){Ok(owner)=>{**retirement=Some(owner);return Ok(metadata())},Err((error,original))=>{**source=Some(original);return Err(error)}}}if let Some(owner)=retirement.as_mut(){if !owner.terminal_is_empty(){let d=nested(RetirementDemand{copy_bytes:owner.next_copy_byte_demand()?,capacity_bytes:owner.next_capacity_byte_demand(grant.maximum_copy_bytes)?,release_bytes:owner.next_release_byte_demand()?,depth:owner.next_depth_demand()?})?;if !permits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let step=poll_step(owner.step(grant.maximum_copy_bytes,&mut effect.nested(RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant})));*work=effect.performed_work();return step.map(|step|RetainedCloneStep::Progress(step.progress()))}if !permits(grant,RetirementDemand{depth:1,..Default::default()}){return Ok(RetainedCloneStep::Progress(Default::default()))}charge(effect,work)?;retirement.take();return Ok(metadata())}Ok(RetainedCloneStep::Complete(Default::default()))}
impl OriginalActorJobState{
 pub fn acknowledge_chunk_on_source(&mut self,job:u64,input:RetainedTurnInput,offset:u64,length:u64,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.borrow_chunk(job,input.operation,input.generation,offset,length).is_none(){return Err(invalid("original output page acknowledgement differs from its held loan").into())}let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);self.job_output_chunk_borrowed=false;Ok(true)}
 pub fn acknowledge_output_on_source(&mut self,job:u64,input:RetainedTurnInput,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.identity!=Some((job,input.operation,input.generation))||!self.ack{return Err(invalid("actor output acknowledgement differs from its completed offer").into())}if cx.retirement_should_yield()||cx.retained_grant().maximum_items==0||cx.retained_grant().maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);self.ack=false;self.identity=None;self.offset=0;Ok(true)}
 pub fn close_source_slot(&mut self,effect:&mut RetainedAllocationEffect<'_>,work:&mut u128)->Result<RetainedCloneStep,ValueError>{close_owned_actor_slot(&mut self.source,&mut self.source_retirement,effect,work)}
 pub fn close_output_slots(&mut self,effect:&mut RetainedAllocationEffect<'_>,work:&mut u128)->Result<RetainedCloneStep,ValueError>{let grant=effect.grant();if self.job_output_chunk_borrowed{return Ok(RetainedCloneStep::Progress(Default::default()))}if self.chunk.is_some()||self.chunk_retirement.is_some(){return close_owned_actor_slot(&mut self.chunk,&mut self.chunk_retirement,effect,work)}if self.output.is_some()||self.output_retirement.is_some(){let turn=close_owned_actor_slot(&mut self.output,&mut self.output_retirement,effect,work)?;if self.output.is_none()&&self.output_retirement.is_none(){self.identity=None;self.offset=0}return Ok(turn)}if self.ack{if !permits(grant,RetirementDemand{depth:1,..Default::default()}){return Ok(RetainedCloneStep::Progress(Default::default()))}charge(effect,work)?;self.ack=false;self.identity=None;self.offset=0;return Ok(metadata())}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub fn close_on_source(&mut self,input:RetainedTurnInput,provider:&mut impl OriginalActorJobProvider,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if provider.identity()!=(input.operation,input.generation){return Err(invalid("actor job provider changed its original identity").into())}if cx.retirement_should_yield(){return Ok(false)}if self.has_source(){let mut work=0u128;let one=RetainedCloneGrant{maximum_items:1,..cx.retained_grant()};let Some((result,_))=cx.with_original_effect(one,|_,effect|self.close_source_slot(effect,&mut work))?else{return Ok(false)};semio_framework_job::receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome{result,work})?;return Ok(false)}if self.has_output(){let mut work=0u128;let one=RetainedCloneGrant{maximum_items:1,..cx.retained_grant()};let Some((turn,_))=cx.with_original_effect(one,|_,effect|self.close_output_slots(effect,&mut work))?else{return Ok(false)};semio_framework_job::receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome{result:turn,work})?;return Ok(false)}let Some(job)=provider.next_owned()else{if cx.retained_grant().maximum_items==0||cx.retained_grant().maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);self.registered=false;return Ok(true)};if !cx.is_cancelled(){let Some(progress)=cx.borrowed_original_cancel_token()?.signal_cancelled_flag_step(cx.retained_grant())else{return Ok(false)};cx.consume_fuel(progress.copied_items as u64);cx.consume_retained(progress)?;return Ok(false)}if provider.is_cancelled(job)==Some(false){provider.cancel(job,cx)?;return Ok(false)}provider.close(job,cx)?;Ok(false)}
 pub const fn empty()->Self{Self{source:ManuallyDrop::new(None),source_retirement:ManuallyDrop::new(None),registered:false,offset:0,ack:false,job_output_chunk_borrowed:false,chunk:ManuallyDrop::new(None),chunk_retirement:ManuallyDrop::new(None),identity:None,output:ManuallyDrop::new(None),output_retirement:ManuallyDrop::new(None)}}
 pub fn source(&self)->Option<&OriginalJobSource>{self.source.as_ref()}
 pub fn output(&self)->Option<&OriginalJobStep>{self.output.as_ref()}
 pub fn retained_chunk(&self)->Option<&[u8]>{self.chunk.as_ref().map(Vec::as_slice)}
 pub fn output_identity(&self)->Option<(u64,u64,u64)>{self.identity}
 pub fn has_source(&self)->bool{self.source.is_some()||self.source_retirement.is_some()}
 pub fn has_output(&self)->bool{self.job_output_chunk_borrowed||self.ack||self.output.is_some()||self.output_retirement.is_some()||self.chunk.is_some()||self.chunk_retirement.is_some()}
 pub fn is_registered(&self)->bool{self.registered}
 pub fn source_is_retiring(&self)->bool{self.source_retirement.is_some()}
 pub fn output_is_retiring(&self)->bool{self.output_retirement.is_some()}
 pub fn outcome(&self)->Option<OriginalJobOutcome>{let(job,operation,generation)=self.identity?;let(state,bytes)=match self.output.as_ref()?{OriginalJobStep::Running(bytes)=>(OriginalJobOutputState::Running,bytes.as_deref().unwrap_or(&[])),OriginalJobStep::Done(bytes)=>(OriginalJobOutputState::Done,&bytes[..]),OriginalJobStep::Failed(bytes)=>(OriginalJobOutputState::Failed,&bytes[..])};Some(OriginalJobOutcome{job,operation,generation,state,byte_length:bytes.len()as u64})}
 pub fn output_demands(&self,copy:usize)->Result<RetirementDemand,ValueError>{if self.job_output_chunk_borrowed||self.ack{return Ok(RetirementDemand{depth:1,..Default::default()})}if self.chunk.is_some()||self.chunk_retirement.is_some(){return slot_demands(&self.chunk,&self.chunk_retirement,copy)}if self.output_retirement.is_some(){return slot_demands(&self.output,&self.output_retirement,copy)}let outcome=self.outcome().ok_or_else(||invalid("actor output is absent"))?;if self.offset<outcome.byte_length as usize{return Ok(RetirementDemand{copy_bytes:usize::from(copy!=0),capacity_bytes:usize::from(copy!=0),depth:1,..Default::default()})}slot_demands(&self.output,&self.output_retirement,copy)}
 pub fn start_on_source(&mut self,incoming:&mut Option<OriginalJobSource>,cx:&mut StepContext<'_>,produce:impl FnOnce(&mut Option<OriginalJobSource>,&mut StepContext<'_>)->Result<bool,ValueError>)->Result<bool,ValueError>{if self.source_retirement.is_some(){return Err(invalid("actor job source is retiring"))}if incoming.is_some(){if self.source.is_some(){return Ok(false)}let grant=cx.retained_grant();if cx.should_yield()||grant.maximum_items==0||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);*self.source=incoming.take();return Ok(false)}if self.source.is_none(){return Err(invalid("actor job retry has no pending source"))}self.registered=true;produce(&mut self.source,cx)}
 pub fn step_on_source(&mut self,job:u64,input:RetainedTurnInput,cx:&mut StepContext<'_>,produce:impl FnOnce(&mut StepContext<'_>)->Result<Option<OriginalJobStep>,OriginalTurnFailure>,reserve:impl FnOnce(&OriginalJobStep,&mut StepContext<'_>)->Result<bool,ValueError>)->Result<Option<OriginalJobStep>,OriginalTurnFailure>{if self.identity.is_some_and(|identity|identity!=(job,input.operation,input.generation))||self.ack||self.output_retirement.is_some(){return Err(invalid("actor job output differs from its retained request or closing phase").into())}if let Some(held)=self.output.as_ref(){let grant=cx.retained_grant();if cx.should_yield()||grant.maximum_items==0||grant.maximum_depth==0||!reserve(held,cx)?{return Ok(None)}cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);self.identity=None;self.offset=0;return Ok(self.output.take())}self.registered=true;if let Some(produced)=produce(cx)?{*self.output=Some(produced);self.offset=0;self.identity=Some((job,input.operation,input.generation))}Ok(None)}
 pub fn borrow_chunk(&self,job:u64,operation:u64,generation:u64,offset:u64,length:u64)->Option<&[u8]>{if !self.job_output_chunk_borrowed||self.identity!=Some((job,operation,generation)){return None}let bytes=self.chunk.as_ref()?;if length!=bytes.len()as u64||offset!=self.offset.checked_sub(bytes.len())?as u64{return None}Some(bytes)}
 pub fn terminal_is_empty(&self)->bool{!self.registered&&!self.has_source()&&!self.has_output()&&self.identity.is_none()}
}
impl Drop for OriginalActorJobState{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"actor job state retains its real source and output until paid retirement")}}

impl OriginalActorJobState{
 pub fn read_on_source<T>(&mut self,job:u64,input:RetainedTurnInput,cancelled:bool,retain:bool,cx:&mut StepContext<'_>,deliver:impl Fn(u64,&mut Option<Vec<u8>>,bool)->T)->Result<T,OriginalTurnFailure>{if self.identity!=Some((job,input.operation,input.generation)){return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original held output read belongs to another source").into())}if self.job_output_chunk_borrowed{return Err(invalid("original output page remains borrowed").into())}let Self{output:job_output,offset:job_output_offset,ack:job_output_ack,output_retirement:job_output_retirement,chunk:job_output_chunk,job_output_chunk_borrowed:job_output_chunk_borrowed,chunk_retirement:job_output_chunk_retirement,..}=self;
   let mut actual_work=0u128;let pending=|offset|deliver(offset as u64,&mut None,false);let available=cx.retained_grant();let grant=RetainedCloneGrant{maximum_items:available.maximum_items.min(usize::try_from(cx.fuel_remaining()).unwrap_or(usize::MAX)),..available};if cx.should_yield()||grant.maximum_items==0||grant.maximum_depth==0{return Ok(pending(*job_output_offset))}
   if *job_output_ack{cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;return Ok(deliver(*job_output_offset as u64,&mut None,true))}
   if cancelled&&!cx.is_cancelled(){let Some(progress)=cx.borrowed_original_cancel_token()?.signal_cancelled_flag_step(grant)else{return Ok(pending(*job_output_offset))};cx.consume_fuel(1);cx.consume_retained(progress)?;return Ok(pending(*job_output_offset))}
   if job_output_chunk.is_some()||job_output_chunk_retirement.is_some(){let Some((step,_))=cx.with_original_effect(grant,|_,effect|close_owned_actor_slot(job_output_chunk,job_output_chunk_retirement,effect,&mut actual_work))?else{return Ok(pending(*job_output_offset))};cx.consume_work(actual_work);let step=step.map_err(|error|OriginalTurnFailure::debit_original(error,cx))?;cx.consume_retained(step.progress())?;return Ok(pending(*job_output_offset))}
   if job_output_retirement.is_some(){let Some((step,_))=cx.with_original_effect(grant,|_,effect|close_owned_actor_slot(job_output,job_output_retirement,effect,&mut actual_work))?else{return Ok(pending(*job_output_offset))};cx.consume_work(actual_work);let step=step.map_err(|error|OriginalTurnFailure::debit_original(error,cx))?;cx.consume_retained(step.progress())?;if job_output.is_none()&&job_output_retirement.is_none(){*job_output_ack=true;return Ok(deliver(*job_output_offset as u64,&mut None,true))}return Ok(pending(*job_output_offset))}
   let bytes=match job_output.as_ref().ok_or_else(||invalid("original output body is absent"))?{OriginalJobStep::Running(bytes)=>bytes.as_deref().unwrap_or(&[]),OriginalJobStep::Done(bytes)|OriginalJobStep::Failed(bytes)=>bytes.as_slice()};let length=bytes.len();if cx.is_cancelled()&&!matches!(job_output.as_ref(),Some(OriginalJobStep::Failed(_))){*job_output_offset=length}
   if *job_output_offset<length{let count=(length-*job_output_offset).min(grant.maximum_copy_bytes).min(grant.maximum_capacity_bytes);if count==0{return Ok(pending(*job_output_offset))}let offset=*job_output_offset;let mut chunk=Vec::new();cx.consume_fuel(1);chunk.try_reserve_exact(count).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original output span allocation refused"))?;let capacity=chunk.capacity();chunk.extend_from_slice(&bytes[offset..offset+count]);**job_output_chunk=Some(chunk);*job_output_offset+=count;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:count,retained_capacity_bytes:capacity,..Default::default()})?;*job_output_chunk_borrowed=retain;return Ok(deliver(offset as u64,job_output_chunk,false))}
   let Some((step,_))=cx.with_original_effect(grant,|_,effect|close_owned_actor_slot(job_output,job_output_retirement,effect,&mut actual_work))?else{return Ok(pending(*job_output_offset))};cx.consume_work(actual_work);let step=step.map_err(|error|OriginalTurnFailure::debit_original(error,cx))?;cx.consume_retained(step.progress())?;if job_output.is_none()&&job_output_retirement.is_none(){*job_output_ack=true;Ok(deliver(*job_output_offset as u64,&mut None,true))}else{Ok(pending(*job_output_offset))}
 }
}
